<article class="content-card">@if(!empty($item['image']))<a href="{{ $item['url'] }}" class="content-card__media"><img src="{{ \Illuminate\Support\Facades\Storage::url($item['image']) }}" alt="" loading="lazy"></a>@else<a href="{{ $item['url'] }}" class="content-card__media content-card__media--empty"><i class="bi bi-stars"></i></a>@endif<div class="content-card__body"><div class="eyebrow"><span>{{ $item['badge'] }}</span>@if($item['category'])<span>· {{ $item['category'] }}</span>@endif</div><h3><a href="{{ $item['url'] }}">{{ $item['title'] }}</a></h3>@if($item['excerpt'])<p>{{ \Illuminate\Support\Str::limit(strip_tags($item['excerpt']),160) }}</p>@endif<div class="content-card__foot"><span class="muted-date">{{ optional($item['published_at'])->translatedFormat('j F') }}</span><a href="{{ $item['url'] }}">Открыть <i class="bi bi-arrow-up-right"></i></a></div></div></article>
